(function(){const hackerEl=document.getElementById("hackerText");if(!hackerEl)return;const messages=["You receive a message from the VXRGX","Hey, I dropped some peace into your wine earlier.."];const glitchChars="!@#$%^&*()_+-=[]{}|;:<>?/~`0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";let msgIndex=0;let isAnimating=false;function randomChar(){return glitchChars[Math.floor(Math.random()*glitchChars.length)]}function sleep(ms){return new Promise((r)=>setTimeout(r,ms))}async function scrambleOut(text){const len=text.length;let chars=text.split("");for(let i=0;i<len;i++){const scrambleCount=1+Math.floor(Math.random()*2);for(let s=0;s<scrambleCount;s++){chars[i]=randomChar();renderChars(chars,i);await sleep(8+Math.random()*8)}chars[i]="";renderChars(chars,i+1);await sleep(4)}hackerEl.textContent=""}async function typeIn(text){let chars=[];for(let i=0;i<text.length;i++){const target=text[i];if(target===" "){chars.push(" ");renderChars(chars,i);await sleep(10+Math.random()*10);continue}const scrambleCount=1+Math.floor(Math.random()*2);for(let s=0;s<scrambleCount;s++){chars[i]=randomChar();renderChars(chars,i);await sleep(10+Math.random()*10)}chars[i]=target;renderChars(chars,-1);await sleep(6+Math.random()*8)}}function renderChars(chars,scrambleIdx){let html="";for(let i=0;i<chars.length;i++){if(chars[i]===""||chars[i]===undefined)continue;const isScrambling=i===scrambleIdx;const c=chars[i]===" "?"&nbsp;":chars[i];html+='<span class="glitch-char'+(isScrambling?" scrambling":"")+'">'+c+"</span>"}hackerEl.innerHTML=html}async function runCycle(){if(isAnimating)return;isAnimating=true;const currentMsg=messages[msgIndex];await typeIn(currentMsg);await sleep(1800+Math.random()*500);await scrambleOut(currentMsg);await sleep(200+Math.random()*150);msgIndex=(msgIndex+1)%messages.length;isAnimating=false;runCycle()}setTimeout(runCycle,800)})();